import {emptyState,readState,queueChanges,mergeSnapshot,acknowledge} from './cloud-core.mjs';
export async function connectMatcha(onRows,onStatus,onAccount){
 const sdk=await import('./firebase-sdk.mjs');let user=null,state=null,epoch=0,off=null,ready=false,error='',serverSeen=false;const flights=new Set();
 const localKey='slowbrew-matcha-local-v1',key=uid=>'slowbrew-matcha-cloud-v1:'+uid;
 const readLocal=()=>{const r=JSON.parse(localStorage.getItem(localKey)||'[]');if(!Array.isArray(r))throw Error('Invalid matcha data');return r};
 const disk=()=>readState(localStorage.getItem(key(user.uid)),user.uid);
 const durable=s=>{localStorage.setItem(key(s.uid),JSON.stringify(s));state=s};
 const show=()=>{onRows((user?state?.records||[]:readLocal()).filter(r=>!r._deleted));onStatus({ready,user:!!user,error,pending:user&&state?Object.keys(state.pending).length:0,serverSeen,hasLocal:user&&readLocal().length>0})};
 function flush(){if(!user||!ready||!navigator.onLine)return;const uid=user.uid,e=epoch;for(const [id,p]of Object.entries(state.pending)){const flight=uid+':'+id;if(flights.has(flight))continue;flights.add(flight);sdk.setDoc(sdk.doc(sdk.db,'users',uid,'matcha',id),{...p.record,_syncToken:p.token,_updatedAt:sdk.serverTimestamp()}).then(()=>{if(e!==epoch)return;durable(acknowledge(disk(),id,p.token));error='';show()}).catch(()=>{if(e===epoch){error='抹茶尚未同步；請檢查網絡及新增抹茶 Firebase 規則。本機待同步資料已保留。';show()}}).finally(()=>{flights.delete(flight);if(e===epoch&&state.pending[id]&&state.pending[id].token!==p.token)flush()})}}
 function listen(){off?.();const e=epoch,uid=user.uid;off=sdk.onSnapshot(sdk.collection(sdk.db,'users',uid,'matcha'),{includeMetadataChanges:true},snap=>{if(e!==epoch)return;try{durable(mergeSnapshot(disk(),snap.docs.map(d=>({id:d.id,data:d.data(),pending:d.metadata.hasPendingWrites})),!snap.metadata.fromCache));if(!snap.metadata.fromCache){serverSeen=true;error=''}show();flush()}catch{error='未能讀取抹茶資料；本機資料已保留。';show()}},()=>{if(e===epoch){error='抹茶尚未同步；請檢查網絡及新增抹茶 Firebase 規則。本機待同步資料已保留。';show()}})}
 sdk.onAuthStateChanged(sdk.auth,u=>{onAccount(null);epoch++;off?.();user=u;state=null;ready=false;error='';serverSeen=false;try{if(u)state=disk();else readLocal();ready=true;onAccount(u?.uid||'local');show();if(u){listen();flush()}}catch{error='未能讀取抹茶本機資料；請保留原檔。';onStatus({ready:false,error})}});
 const api={save(row){if(!ready)return false;try{const current=user?disk().records:readLocal();if(current.some(r=>r.id===row.id&&r._deleted&&!row._deleted)){error='此抹茶記錄已刪除，未能覆蓋。';show();return false}if(!user){const rows=readLocal();localStorage.setItem(localKey,JSON.stringify([...rows.filter(r=>r.id!==row.id),row]));show()}else{durable(queueChanges(disk(),state.records,[row],()=>crypto.randomUUID()));show();flush()}return true}catch{error='抹茶儲存失敗，請保留此畫面。';onStatus({ready,user:!!user,error});return false}},retry(){if(user){error='';listen();flush()}},async importLocal(){if(!user||!serverSeen)return;const e=epoch;try{const snap=await sdk.getDocsFromServer(sdk.collection(sdk.db,'users',user.uid,'matcha'));if(e!==epoch)return;const s=disk(),known=new Set([...s.records.map(r=>r.id),...snap.docs.map(d=>d.id)]);durable(queueChanges(s,[],readLocal().filter(r=>!known.has(r.id)),()=>crypto.randomUUID()));show();flush()}catch{error='未能匯入本機抹茶紀錄；原檔已保留。';show()}}};
 window.addEventListener('online',()=>{if(user){listen();flush()}});window.addEventListener('storage',e=>{if(user&&e.key===key(user.uid)){try{state=disk();show();flush()}catch{}}else if(!user&&e.key===localKey)show()});return api;
}
